    with open('../outputs/results.json', 'w') as f:
        json.dump(results, f, indent=2)", "new_str": "    # Save results - convert numpy arrays to lists for JSON serialization
    def convert_to_serializable(obj):
        if isinstance(obj, np.ndarray):
            return obj.tolist()
        elif isinstance(obj, (np.integer, np.floating)):
            return float(obj)
        elif isinstance(obj, complex):
            return {'real': float(obj.real), 'imag': float(obj.imag)}
        elif isinstance(obj, dict):
            return {k: convert_to_serializable(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [convert_to_serializable(item) for item in obj]
        return obj

    results = {
        'z_grid': z_grid.tolist(),
        'K_points': K_points.tolist(),
        'hinf_verification': convert_to_serializable(hinf_results),
        'simulation1': convert_to_serializable(sim1),
        'simulation2': convert_to_serializable(sim2),
        'simulation3': convert_to_serializable(sim3)
    }

    with open('../outputs/results.json', 'w') as f:
        json.dump(results, f, indent=2)"}<|tool_call_end|><|tool_calls_section_end|>
